<script setup lang="ts">
import type { WorkshopSchedule } from '../../lib/homebrew-workshop'
const props=defineProps<{ modelValue:WorkshopSchedule[]; label:string; maximum?:number }>()
const emit=defineEmits<{ 'update:modelValue':[value:WorkshopSchedule[]] }>()
function change(index:number,key:keyof WorkshopSchedule,value:number){emit('update:modelValue',props.modelValue.map((row,i)=>i===index?{...row,[key]:value}:row))}
function add(){const last=[...props.modelValue].sort((a,b)=>b.level-a.level)[0];emit('update:modelValue',[...props.modelValue,{level:Math.min(20,(last?.level??0)+1),total:last?.total??0}])}
</script>
<template><div class="hw-schedule"><div class="hw-between"><h4>{{label}}</h4><button type="button" class="hw-text-button" :disabled="modelValue.length>=20" @click="add">+ Add level</button></div><p class="hw-hint">Enter the total available from that level onward. Later rows replace earlier totals.</p><p v-if="!modelValue.length" class="hw-empty-inline">No progression recorded.</p><div v-if="modelValue.length" class="hw-schedule-rows" role="region" :aria-label="`${label} progression`" tabindex="0"><div v-for="(row,index) in modelValue" :key="index" class="hw-schedule-row"><label>From level<input :value="row.level" type="number" min="1" max="20" :aria-label="`${label}: level ${index+1}`" @input="change(index,'level',Number(($event.target as HTMLInputElement).value))" /></label><label>Total<input :value="row.total" type="number" min="0" :max="maximum??99" :aria-label="`${label}: total ${index+1}`" @input="change(index,'total',Number(($event.target as HTMLInputElement).value))" /></label><button type="button" class="hw-icon-button" :aria-label="`Remove ${label.toLowerCase()} row ${index+1}`" @click="emit('update:modelValue',modelValue.filter((_,i)=>i!==index))">×</button></div></div></div></template>
